int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long c1, c2;
    if (!(cin >> n >> c1 >> c2)) return 0;
    string s;
    cin >> s;

    int adults = 0;
    for (char ch : s) if (ch == '1') adults++;

    long long ans = LLONG_MAX;

    // Option 1: all in one group
    {
        long long cost = c1 + c2 * 1LL * (n - 1) * (n - 1);
        ans = min(ans, cost);
    }

    // Option 2: split into groups of size 1 or 2
    // Each group must contain at least one adult.
    // Adults can be alone (size 1) or with one pupil (size 2).
    int pupils = n - adults;

    // If pupils > adults, some pupils would have to be alone, which is impossible.
    if (pupils <= adults) {
        long long cost = 0;
        int pairs = pupils;          // each pupil paired with an adult
        int singles = adults - pairs; // remaining adults alone

        // cost for pairs (size 2 groups)
        cost += pairs * (c1 + c2 * 1LL * (2 - 1) * (2 - 1));
        // cost for single adults (size 1 groups)
        cost += singles * c1;

        ans = min(ans, cost);
    }

    cout << ans << '\n';
    return 0;
}

