#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long c1, c2;
    if (!(cin >> n >> c1 >> c2)) return 0;
    string s;
    cin >> s;

    int adults = 0;
    for (char ch : s) if (ch == '1') adults++;

    long long best = LLONG_MAX;

    for (int g = 1; g <= adults; ++g) {
        int base = adults / g;
        int rem = adults % g;
        long long groups = g;

        long long sum_x = 1LL * base * (g - rem) + 1LL * (base + 1) * rem;
        long long pupils = n - adults;
        long long extra = pupils - sum_x;
        if (extra < 0) continue;

        long long add = extra / g;
        int rem2 = extra % g;

        long long x_small = base + add;
        long long x_big = base + add + 1;

        long long cnt_big = rem2;
        long long cnt_small = g - rem2;

        long long cost = groups * c1;
        long long sq_small = 1LL * x_small * x_small;
        long long sq_big = 1LL * x_big * x_big;
        cost += c2 * (cnt_small * sq_small + cnt_big * sq_big);

        if (cost < best) best = cost;
    }

    cout << best << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long c1, c2;
    if (!(cin >> n >> c1 >> c2)) return 0;
    string s;
    cin >> s;

    int adults = 0;
    for (char ch : s) if (ch == '1') adults++;

    // If only adults, optimal is one group of all
    if (adults == n) {
        long long x = n;
        cout << c1 + c2 * (x - 1) * (x - 1) << '\n';
        return 0;
    }

    // If c2 <= 0 (not possible by constraints) or grouping all is best
    // But we must ensure each group has at least one adult.
    // General DP: dp[k] = minimal cost to cover k people (k from 0..n)
    // with groups that each contain at least one adult.
    // However, we don't know adult positions per group; but constraint is only count of adults >= groups.
    // Optimal strategy: each group must have at least one adult, so number of groups <= adults.
    // For given number of groups g (1..adults), we can partition n people into g groups of sizes x_i>=1.
    // Cost depends only on sizes: sum c1 + c2*(x_i-1)^2.
    // Minimize sum of squares given sum x_i = n and x_i>=1.
    // This is minimized when sizes are as equal as possible.

    long long ans = LLONG_MAX;
    for (int g = 1; g <= adults; ++g) {
        int base = n / g;
        int rem = n % g;
        // rem groups of size base+1, g-rem groups of size base
        long long cost = 0;
        // groups of size base+1
        if (base + 1 >= 1) {
            long long x = base + 1;
            long long val = c1 + c2 * (x - 1) * (x - 1);
            cost += (long long)rem * val;
        }
        // groups of size base
        if (base >= 1) {
            long long x = base;
            long long val = c1 + c2 * (x - 1) * (x - 1);
            cost += (long long)(g - rem) * val;
        }
        ans = min(ans, cost);
    }

    cout << ans << '\n';
    return 0;
}

