int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long c1, c2;
    if (!(cin >> n >> c1 >> c2)) return 0;
    string s;
    cin >> s;

    vector<int> adults;
    adults.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (s[i] == '1') adults.push_back(i);
    }

    int A = adults.size();
    vector<long long> dp(A + 1, (long long)4e18);
    dp[0] = 0;

    for (int i = 1; i <= A; ++i) {
        long long best = (long long)4e18;
        // j is the first adult in the current group, i-1 is the last
        for (int j = i - 1; j >= 0; --j) {
            int left = adults[j];
            int right = adults[i - 1];
            int x = right - left + 1; // group size
            long long cost = c1 + c2 * 1LL * (x - 1) * (x - 1);
            best = min(best, dp[j] + cost);
        }
        dp[i] = best;
    }

    cout << dp[A] << '\n';
    return 0;
}

