    int adults = 0;
    for (char ch : s) if (ch == '1') adults++;

    long long ans = LLONG_MAX;

    // Try all possible number of groups g from 1 to adults
    for (int g = 1; g <= adults; ++g) {
        int base = adults / g;
        int rem = adults % g; // first rem groups have size base+1, others base

        long long cost = 0;
        // rem groups of size base+1
        if (base + 1 > 0) {
            long long x = base + 1;
            cost += (long long)rem * (c1 + c2 * (x - 1) * (x - 1));
        }
        // g - rem groups of size base
        if (base > 0) {
            long long x = base;
            cost += (long long)(g - rem) * (c1 + c2 * (x - 1) * (x - 1));
        }
        ans = min(ans, cost);
    }

    cout << ans << '\n';
    return 0;
}

