int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long c1, c2;
    if (!(cin >> n >> c1 >> c2)) return 0;
    string s;
    cin >> s;

    int adults = 0;
    for (char ch : s) if (ch == '1') adults++;

    const long long INF = (long long)4e18;
    vector<long long> dp(adults + 1, INF);
    dp[0] = 0;

    for (int i = 1; i <= adults; ++i) {
        long long best = INF;
        for (int j = 1; j <= i; ++j) {
            long long cost = dp[i - j] + c1 + c2 * 1LL * (j - 1) * (j - 1);
            if (cost < best) best = cost;
        }
        dp[i] = best;
    }

    cout << dp[adults] << '\n';
    return 0;
}
